  for (let q = 0; q < k; q++) {
    const a = o + 3 * q, b = o + 3 * ((q + 1) % k);
    x += (C[a + 1] - C[b + 1]) * (C[a + 2] + C[b + 2]); y += (C[a + 2] - C[b + 2]) * (C[a] + C[b]); z += (C[a] - C[b]) * (C[a + 1] + C[b + 1]);
  }
