    const inward = !!ref && nrm[0] * ref[0] + nrm[1] * ref[1] + nrm[2] * ref[2] < 0;  // no ref: as listed
    poly[sides * i] = t[0];
    for (let q = 1; q < sides; q++) poly[sides * i + q] = t[inward ? sides - q : q];
    const l = Math.hypot(nrm[0], nrm[1], nrm[2]) * (inward ? -1 : 1);
