const walkName = (w) => splitModeLabel(modeOptionOf(w)?.text ?? w).name;
// a mode's shape and its tiles, as the Grid's menu names them: a surface of a family (a torus, a strip, a bottle, the
// rosettes' spheres) and its tiles there (Torus · Kites, Rosettes · Flower 9); else its space and its shape, its tiles in its
// name (2D circles · Flower 9, 3D solids · Cube)
const shapeAndTiles = (w) => { const f = familyOf(w), t = f?.F.tabs.find(([m]) => m === f.m); return t ? `${NAV[w][2]} · ${shapeLabel(t[3])}` : `${SPACES[NAV[w][1]]?.[0]} · ${NAV[w][2]}`; };
// the setup in use (a Treasure's row lit, the ☆ lit): all of it the same (its number, walk, size, start, rule, colours,
// symmetry, edges, cells drawn or found…) but its version, its length (a hover cuts it, see preview) and how it is looked at
// (Fill areas, Space-time)
const SETUP_LOOKS = ['v', 'd', 'fa', 'sp'];
const isInUse = (setup) => sameSetup(setup, getSetup(), SETUP_LOOKS);
let galleryBefore = null, galleryHover = 0;  // the setup in use while others are shown on hover
// and its view (Auto-fit, Auto-rotate, camera, framing): a setup shown on hover is framed (Auto-fit on)
// and, in 3D, turning (Auto-rotate on); a click keeps that, turning on; leaving the list brings back
// the setup in use as it was seen
let galleryView = null;
// and what is not in a link: the hunt's zone, goal and results (all of it, kept in one place)
const viewNow = () => ({ autoFit: $('autoFit').checked, autoRotate: $('autoRotate').checked, cam: { r: [...cam.r], u: [...cam.u], v: [...cam.v] }, view: { ...view },
  hunt: { zone: hunt.zone, goal: hunt.goal, top: hunt.top, picked: hunt.picked, status: hunt.status } });
// A setup's row, built-in or saved: the walk's icon, a name and a detail; hovering shows it, a click
// keeps it (see the lists' mouseleave); with onDelete, a × at its end
// A setup of the Gallery is shown framed and facing its walk: Auto-fit on (a hand rotation or zoom
// may have turned it off, and the walk could be on the far side), kept only by a click
function showSetup(setup) {  // framed and faced once built (see showAll), not before: the walk is built apart
  $('autoFit').checked = true;
  $('autoRotate').checked = false;  // still while it is faced (faceWalk does not turn a turning view)
  spinFrom = 0;
  pendingSpin = true;  // then turning, in 3D, a moment later (see applyPendingView)
  applySetup(setup);
}
const preview = (setup) => (setup.d > 5000 ? { ...setup, d: 5000 } : setup);  // (a setup hovered: its first 5,000 digits or steps, at once; clicked, all of them)
function setupRow(name, detail, setup, onDelete) {
  const b = card({ pic: icon(SHAPE_ICONS[NAV[setup.w]?.[2]] ?? MODE_ICONS[setup.w]), name, detail, on: !galleryBefore && isInUse(setup) });  // (its shape's picture, as the Grid's; its tooltip its name and its detail in full, as the row may cut them short)
  if (onDelete) {
    b.append(rowAction('×', `Delete “${name}”`, onDelete));
  }
  b.setAttribute('role', 'option');
  b.addEventListener('mouseenter', () => {
    ruleTutorial(null);  // what lies over the view (how a rule works, the digits) closes: the setup shown instead
    closeNumber();
    clearTimeout(galleryHover);
    galleryHover = setTimeout(() => { if (!galleryBefore) { galleryBefore = getSetup(); galleryView = viewNow(); } showSetup(preview(setup)); }, 120);
  });
  b.addEventListener('click', () => {
    clearTimeout(galleryHover);
    if (!galleryBefore || !isInUse(setup) || preview(setup) !== setup) showSetup(setup);  // (shown cut short: all of it now; isInUse leaves its digits out)
    pendingSpin = false;  // clicked while still: it stays still (already turning: it goes on)
    spinFrom = 0;
    galleryBefore = galleryView = null;  // kept, Auto-fit on: leaving the list no longer brings back the one before
    syncLink();  // its link (if already built; else once built)
    renderModePicker();  // its tab, at the top
    showPane(false);  // and its parameters
  });
  return b;
}
function renderGallery() {
  fillSetupList();
}
for (const list of ['yourList']) {
  $(list).addEventListener('mouseleave', () => {
    clearTimeout(galleryHover);
    if (!galleryBefore) return;
    const before = galleryBefore;
    galleryBefore = null;
    pendingRestore = galleryView;
    galleryView = null;
    pendingSpin = false;
    spinFrom = 0;
    applySetup(before);
  });
}
// The left pane shows the parameters, or the gallery: opened by a click on the Gallery tab (lit as the tab in use), closed by
// it again or by a Close (by each of its titles, as How it works), a setup clicked or another tab: the parameters of the tab before
function showPane(gallery) {
  $('paramsPane').hidden = gallery;
  $('galleryPane').hidden = !gallery;
  galleryTab().classList.toggle('open', gallery);
  if (gallery) renderGallery();
}
const galleryButton = document.createElement('button');
$('galleryPane').addEventListener('click', (e) => { if (e.target.closest('.gallery-close')) showPane(false); });  // (each section's Close)
function galleryTab() {
  if (galleryButton.dataset.ready) return galleryButton;
  const b = galleryButton;
  b.dataset.ready = '1';
  b.className = 'pane-tab';
  b.innerHTML = `<span class="fav" role="button">${icon('star')}</span> Gallery`;  // (its picture the ☆ Save, see syncSaveButton)
  b.title = 'Treasures and the curated setups: hover one to see it, click it to keep it';
  b.addEventListener('click', (e) => { if (e.target.closest('.fav')) saveSetup(); else showPane($('galleryPane').hidden); });
  return b;
}

// Treasures' tools, tiles: Import (added to them, a name already used numbered), Export, Erase all (then Confirm erase, under them),
// then Share (the link to what is shown)
$('setupTools').replaceChildren(tile({ pic: icon('import'), text: 'Import', title: 'Add the setups of a JSON file to Treasures (those of a name already used numbered: none replaced)', click: () => $('setupFile').click() }),
  tile({ pic: icon('export'), text: 'Export', title: 'Treasures as a JSON file', click: exportSetups }), tile({ pic: icon('trash'), text: 'Erase all', title: 'Erase Treasures from this browser (asked again under it)', click: () => { $('eraseConfirm').hidden = !$('eraseConfirm').hidden; } }),
  tile({ pic: icon('link'), text: 'Share', title: 'Copy the link to what is shown', click: () => shareView($('setupTools').lastElementChild) }));
$('eraseConfirm').innerHTML = `${icon('trash')} Confirm erase`;
$('setupToolsHead').insertAdjacentHTML('afterbegin', icon('floppy'));  // (Treasures' files: Import, Export, Erase)
$('eraseConfirm').addEventListener('click', () => { writeSetups([]); $('eraseConfirm').hidden = true; fillSetupList(); });
$('setupFile').addEventListener('change', () => {
  if ($('setupFile').files[0]) importSetups($('setupFile').files[0]);
  $('setupFile').value = '';
});
// a setup link pasted into this tab
window.addEventListener('hashchange', () => { const s = parseHash(); if (s) applySetup(s); });


/* ---- 12.3 Start-up --------------------------------------------------------------------------- */
// A link with a setup opens that setup; otherwise Life on the cube. The link then follows the setup on its events (see
// syncLink).
new ResizeObserver(resize).observe(stage);
new ResizeObserver(() => { statsDirty = true; }).observe($('animBar'));  // the bar opened or closed: its digits fill its new width
updateSpeedLabel();
resize();
requestAnimationFrame(tick);
$('appTab').innerHTML = `${appLogo()} ${APP_TITLE} v${VERSION}`;
$('favicon').href = `data:image/svg+xml,${encodeURIComponent(appLogo(cssColour('--accent')))}`;
// Credits: the people whose work it shows, a page in the middle pane as How it works, opened and closed by the app's tab (π,
// its name and version; lit while it shows, as Gallery's); closed as How it works is, by a click elsewhere; Share and Home there
const creditsShown = () => !$('ruleTuto').hidden && $('ruleTuto').dataset.shown === 'credits';
const AUTHOR = '🇫🇷 Vincent ᗱƆᑌᑎϹᗴ 👾 · <b>𝕏 <a href="https://x.com/VincentBounce" target="_blank" rel="noopener">@VincentBounce</a></b>';  // (its author, as signed)
const CREDITS = [
  ['Life and its kin', "John Conway's Game of Life; Edward Fredkin's Replicator; Rudy Rucker and John Walker's Faders; Alan Hensel's letters for squares, Paul Callahan's for hexagons; Norman Margolus and Tommaso Toffoli's blocks; Gérard Vichniac's Q2R; Tim Tyler's cell-auto.com (Q*Bert, Square-4, stellated blocks); Stephen Wolfram's elementary rules; Chris Langton's ant and loop, John Byl's loop; Mike Paterson and John Conway's worms; Golly and LifeWiki (RLE, patterns)"],
  ['Numbers', "the Chudnovsky brothers (π), Brent and McMillan (γ), Amdeberhan and Zeilberger (ζ(3)), Lupaș (Catalan's constant), all by binary splitting; Stanisław Ulam's spiral"],
  ['Tilings', "Roger Penrose; Robert Ammann and F. Beenker; N. G. de Bruijn's multigrids; Smith, Myers, Kaplan and Goodman-Strauss's hat and spectre; Conway and Radin's pinwheel; Hirschhorn and Hunt's flower; Teruhisa Sugimoto's rosettes, rings and hexagon rosettes; Bernhard Klaassen's rotational tilings; Tom Ruen's mirrored rosette (Wikimedia); Adams, Edgar, Hollander and Jacoby's kaleidoscope; Rolf Stein's pentagon; Jaap Scherphuis's Tiling Viewer; Goldberg's polyhedra, Menger's sponge, Paul Bourke's Klein bottle; Tutte's embedding and Floater's mean value weights (the rosette spheres)"],
  ['Prototypes', "Bert Chan's Lenia, Tom Mohr's Particle Life, Jeff Jones's Physarum, Tim Hutton's Squirm3"],
];
function credits(open) {
  ruleTutorial(null);
  if (!open) return;
  $('appTab').classList.add('open');
  $('ruleTuto').hidden = false;
  $('ruleTuto').dataset.shown = 'credits';
  $('ruleTuto').innerHTML = `<div class="tut-body"><h3>${APP_TITLE} <code>v${VERSION}</code></h3><p>Made by ${AUTHOR}</p><p>Cellular automata on tilings, surfaces and solids, and walks on the digits of numbers: the work of many, here.</p>`
    + CREDITS.map(([title, who]) => `<h4>${title}</h4><p>${who}.</p>`).join('')
    + `<p><a href="https://github.com/VincentBounce/Tessera#readme" target="_blank" rel="noopener">Its README</a> · <a href="https://github.com/VincentBounce/Tessera" target="_blank" rel="noopener">its code</a></p></div>`;
  $('ruleTuto').prepend(tutTools({ words: [['Share', 'Copy the link to what is shown', (e) => shareView(e.currentTarget)], ['Home', 'Back to the start', () => { location.href = location.pathname; }]], close: () => credits(false) }));
}
$('appTab').addEventListener('click', () => credits(!creditsShown()));
for (const b of document.querySelectorAll('[data-icon]')) b.insertAdjacentHTML('afterbegin', icon(b.dataset.icon));
play(false);  // the Play button with its icon
seedCurated();
fillSetupList();
// the card first (its device asked once, see gpuSetup); then a link with a setup opens that setup; otherwise Life, the first
// tab: 6 colours at war on the cube
const linked = parseHash() ?? { w: 'lifeCube', s: '48', r: 'B3/S23', k: '6', pop: 'random.49.8259995' };
gpuSetup().catch((e) => { console.warn('WebGPU off:', e.message); GPU = false; }).then(() => { if (!linked || !applySetup(linked)) compute(); });
showPane(false);
